insert into practice_exercises (id, subject_name, level, title, source) values
  ('0df26980-8627-4ae4-bfc8-90d7951e6dbe', $$Natuurkunde$$, $$HAVO$$, $$Gasniveau meten$$, $$HAVO Natuurkunde 2023-I$$),
  ('6f642084-5756-41f6-901f-42386e791087', $$Natuurkunde$$, $$HAVO$$, $$Noodstopstrook$$, $$HAVO Natuurkunde 2023-I$$),
  ('58545be6-d765-46bb-b69d-e146f058efeb', $$Natuurkunde$$, $$HAVO$$, $$Kosmische explosie$$, $$HAVO Natuurkunde 2023-I$$),
  ('b6410ed6-5cc0-4063-969d-e655de52f156', $$Natuurkunde$$, $$HAVO$$, $$Radioactieve rook$$, $$HAVO Natuurkunde 2023-I$$),
  ('b86a9736-8098-4714-8782-a706c4ba620d', $$Natuurkunde$$, $$HAVO$$, $$Zelfbouw zaklamp$$, $$HAVO Natuurkunde 2023-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('c301e25f-2422-4168-b531-e73a91b350f0', '0df26980-8627-4ae4-bfc8-90d7951e6dbe', $$intro gasbarbecue; figuur 1 — gasbarbecue met stalen gasfles; max 6,1 kg propaan; vermogen 15 kW, stookwaarde 13,8 kWh kg⁻¹$$, $$natuurkunde-havo-2023-i-gasniveau-meten-context1.png$$, 498, $$Een gasbarbecue gebruikt gas uit een stalen gasfles als energiebron. Zie figuur 1.

figuur 1: zwart-witfoto van een gasbarbecue met een stalen gasfles ervoor op een terras.

Hans en Sanne doen onderzoek naar verschillende methodes om te bepalen hoe vol een stalen gasfles is. Een lege gasfles kan gevuld worden met maximaal 6,1 kg vloeibaar propaan.
Hans en Sanne hebben een barbecue met een vermogen van 15 kW. De stookwaarde van vloeibaar propaan is 13,8 kWh kg⁻¹.$$, 'inline'),
  ('fbf81019-31d5-49d6-9232-8f04409ceb59', '0df26980-8627-4ae4-bfc8-90d7951e6dbe', $$afkoeling fles door faseovergang propaan/waterdamp; uitwerkbijlage twee zinnen$$, $$natuurkunde-havo-2023-i-gasniveau-meten-context2.png$$, 498, $$Ze merken dat na een tijd barbecueën de buitenzijde van de fles koud aanvoelt en dat er waterdruppels op de fles ontstaan. Ze beredeneren dat het vloeistofpeil van het propaan ongeveer gelijk moet staan aan de bovenrand van de waterdruppels op de fles. Ze concluderen dat de fles afkoelt door de faseovergang van het propaan in de fles van vloeibaar naar gasvormig.
Op de uitwerkbijlage staan twee zinnen.$$, 'inline'),
  ('0183b7c3-4fb3-4f8f-870e-cf32f534fb76', '0df26980-8627-4ae4-bfc8-90d7951e6dbe', $$uitwerkbijlage vraag 2 — twee zinnen met faseovergangen om het juiste antwoord te omcirkelen$$, $$natuurkunde-havo-2023-i-gasniveau-meten-context7.png$$, 498, $$Uitwerkbijlage vraag 2: ''De faseovergang van vloeibaar naar gasvormig propaan in de fles heet smelten / stollen / verdampen / condenseren / sublimeren.'' en ''De faseovergang van waterdamp naar waterdruppels op de buitenzijde van de fles heet smelten / stollen / verdampen / condenseren / sublimeren.'', met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('f88b3d09-f3f7-4859-95eb-ec5ca6a15543', '0df26980-8627-4ae4-bfc8-90d7951e6dbe', $$figuur 2 — grondtoon-frequentie tegen vulstand (%) van de gasfles$$, $$natuurkunde-havo-2023-i-gasniveau-meten-context3.png$$, 498, $$Wanneer Hans tegen de gasfles slaat, produceert deze een toon. Hij vraagt zich af of deze toon afhankelijk is van de vulstand van de fles. Tijdens het vullen van een fles bepaalt Hans de frequentie van de grondtonen die de gasfles produceert bij verschillende vulstanden, van leeg tot vol. Hiervan maakt hij een diagram. Hierin is de vulstand als percentage weergegeven. Zie figuur 2.

figuur 2: grafiek van de frequentie van de grondtoon (Hz) tegen de vulstand (%) van de gasfles, van leeg (0%) tot vol (100%).$$, 'inline'),
  ('65be25e6-0012-44c6-8d88-bb8c4ded20b7', '0df26980-8627-4ae4-bfc8-90d7951e6dbe', $$figuur 3 — schematische staande golf in de gaslaag boven de vloeistof$$, $$natuurkunde-havo-2023-i-gasniveau-meten-context4.png$$, 498, $$Bij elke vulstand is er een laag gas boven de vloeistof. Hans denkt dat de tonen ontstaan door een staande golf in dit gas. Zie schematisch in figuur 3.

figuur 3: schematische tekening van een gasfles met daarin een vloeistofpeil en, in de gaslaag daarboven, een dubbele pijl die de staande golf aangeeft.$$, 'inline'),
  ('ad96795e-f120-4c75-a4b5-37547122530c', '0df26980-8627-4ae4-bfc8-90d7951e6dbe', $$figuur 4/5 — trillende gasfles als snaar met 4 knopen K en 4 buiken B, omtrek 72 cm; frequentie lege fles 1,50·10³ Hz$$, $$natuurkunde-havo-2023-i-gasniveau-meten-context5.png$$, 498, $$Sanne heeft een andere verklaring voor de toon. Zij denkt dat de gasfles zelf als een soort snaar werkt. Op de omtrek van de gasfles ontstaat dan een staande golf met vier knopen K en vier buiken B, net als bij een trillend wijnglas. Zie figuur 4 en schematisch in figuur 5.

figuur 4: foto van een trillend wijnglas.
figuur 5: schematische bovenaanzichttekening van de omtrek van de gasfles met daarop een staande golf met vier knopen (K) en vier buiken (B).

De gasfles is gemaakt van staal en heeft een omtrek van 72 cm. De frequentie van de toon van de lege gasfles is 1,50·10³ Hz.$$, 'inline'),
  ('869f6943-adfb-4af1-88b3-e2d5e577a66e', '0df26980-8627-4ae4-bfc8-90d7951e6dbe', $$figuur 6 — oscillogram (screenshot oscilloscoop-app) van de toon van een gedeeltelijk gevulde gasfles$$, $$natuurkunde-havo-2023-i-gasniveau-meten-context6.png$$, 498, $$Hans en Sanne proberen of ze met behulp van figuur 2 de vulstand van een gedeeltelijk gevulde gasfles kunnen bepalen. Ze gebruiken een oscilloscoop-app. Met hun telefoon maken ze een oscillogram van de toon die ontstaat door het aanslaan van de fles. Zie het screenshot in figuur 6.

figuur 6: screenshot van een oscilloscoop-app met het oscillogram (uitwijking tegen tijd) van de toon van de gedeeltelijk gevulde gasfles.$$, 'inline'),
  ('296bf6a2-e5c4-484a-9208-b36e5e7a1516', '6f642084-5756-41f6-901f-42386e791087', $$intro noodstopstrook (grindbak); figuur 1 — noodstopstrook naast snelweg; figuur 2 — (v,t)-diagram remmende vrachtwagen in het grind$$, $$natuurkunde-havo-2023-i-noodstopstrook-context1.png$$, 498, $$In bergachtige gebieden liggen naast snelwegen vaak noodstopstroken. Een noodstopstrook is een lange bak, gevuld met grind. Zie figuur 1.

figuur 1: luchtfoto van een noodstopstrook (een oplopende baan gevuld met grind) naast een snelweg in een bergachtig gebied.

Als de remmen van een vrachtwagen tijdens het afdalen weigeren, kan de chauffeur de noodstopstrook gebruiken. Hoe verder de vrachtwagen de strook oprijdt, hoe dieper de grindlaag wordt waar de vrachtwagen doorheen rijdt. De remkracht van het grind op de vrachtwagen neemt daardoor toe.

Van een remmende vrachtwagen in het grind is een (v,t)-diagram gemaakt. Zie figuur 2.

figuur 2: (v,t)-diagram met v (m s⁻¹, 0 tot 30) op de verticale as en t (s, 0 tot 10) op de horizontale as; een dalende kromme die bij ongeveer (0; 25) begint, aanvankelijk vlak verloopt en steeds steiler dalend eindigt bij ongeveer (9; 0).

Figuur 2 is ook op de uitwerkbijlage afgedrukt.$$, 'inline'),
  ('d97e6ced-cb7c-42bc-b17a-ace61bb4688e', '6f642084-5756-41f6-901f-42386e791087', $$ontwerp-eis: vertraging vrachtwagen mag niet groter zijn dan 0,90·g$$, $$natuurkunde-havo-2023-i-noodstopstrook-context2.png$$, 498, $$Uit veiligheidsoverwegingen is een ontwerp-eis van een noodstopstrook dat de vertraging van de vrachtwagen niet groter mag zijn dan 0,90∙g.
Figuur 2 is nogmaals op de uitwerkbijlage afgedrukt.$$, 'inline'),
  ('ae2f6475-59c7-4104-b555-5d6a71d5a306', '6f642084-5756-41f6-901f-42386e791087', $$grind kan bevriezen in koude gebieden waardoor vrachtwagen minder ver wegzakt$$, $$natuurkunde-havo-2023-i-noodstopstrook-context3.png$$, 498, $$In koude gebieden kan het grind aan elkaar vriezen, waardoor de vrachtwagen er niet meer zo ver in wegzakt.
Figuur 2 is nogmaals op de uitwerkbijlage afgedrukt.$$, 'inline'),
  ('7a17159b-6dc7-48c6-8da5-28b905e28a5a', '6f642084-5756-41f6-901f-42386e791087', $$Canadees ontwerp met vangnetten aan trommels met stalen band i.p.v. grind; figuur 3/4 — trommels en vangnetten$$, $$natuurkunde-havo-2023-i-noodstopstrook-context4.png$$, 498, $$In Canada is een nieuw ontwerp uitgewerkt voor een noodstopstrook waar vorst geen invloed op heeft. In plaats van grind worden vangnetten gebruikt om de vrachtwagen af te remmen. De vangnetten zitten vast aan trommels. In elke trommel bevindt zich een opgerolde stalen band waar de vangnetten aan zijn bevestigd. Zie figuren 3 en 4.

figuur 3: foto van een aantal trommels met stalen banden, gemonteerd in de wand van een noodstopstrook.
figuur 4: close-upfoto van een trommel met de opgerolde stalen band waaraan het vangnet is bevestigd.$$, 'inline'),
  ('5a246407-450a-4d17-b65e-8575b2bd1e2b', '6f642084-5756-41f6-901f-42386e791087', $$afrollende band trekt aan net; constante spankracht Fs; figuur 5 — schema spankracht op net (niet op schaal)$$, $$natuurkunde-havo-2023-i-noodstopstrook-context5.png$$, 498, $$Als een vrachtwagen een net raakt, worden de banden uit de trommels getrokken. Iedere stalen band trekt tijdens het afrollen aan het net. Hierdoor ontstaat in het net een constante spankracht Fs. Dit is schematisch weergegeven in figuur 5. Deze figuur is niet op schaal.

figuur 5: schematische tekening (niet op schaal) van een net dat via stalen banden aan trommels vastzit, met de spankracht Fs die op het net werkt aangegeven.$$, 'inline'),
  ('cf9bd4b8-c185-457a-8419-a67e5b2ac4b0', '6f642084-5756-41f6-901f-42386e791087', $$remkracht Frem door spankracht Fs; uitwerkbijlage toont situaties I en II; klassieke grindstrook geeft steeds grotere remkracht$$, $$natuurkunde-havo-2023-i-noodstopstrook-context6.png$$, 498, $$Door de constante spankracht Fs werkt er een remkracht Frem op de vrachtwagen. Op de uitwerkbijlage zijn twee situaties, I en II, vereenvoudigd weergegeven. De klassieke grindstrook levert een steeds grotere remkracht als de vrachtwagen verder het grind in rijdt.$$, 'inline'),
  ('02177e13-a0a4-41be-8629-fb59377d1bd5', '6f642084-5756-41f6-901f-42386e791087', $$band rolt af bij spankracht 2,0·10⁴ N; roestvrij staal, elastisch uitgerekt, breedte 5,0 cm, dikte 3,0 mm; figuur 6 — afmetingen band$$, $$natuurkunde-havo-2023-i-noodstopstrook-context7.png$$, 498, $$Een band rolt af bij een spankracht van 2,0·10⁴ N. De band is gemaakt van roestvrij staal en wordt elastisch uitgerekt. De band is 5,0 cm breed en 3,0 mm dik. Zie figuur 6.
Een ontwerp-eis is dat de band niet te ver mag uitrekken tijdens het afremmen.

figuur 6: schematische tekening van een stuk stalen band met de afmetingen breedte 5,0 cm en dikte 3,0 mm aangegeven.$$, 'inline'),
  ('6fac96ab-06dc-4b99-b4e3-7ef0f3bd53c8', '6f642084-5756-41f6-901f-42386e791087', $$meerdere vangnetten achter elkaar, elk aan meerdere identieke trommels; figuur 7 — drie vangnetten in noodstopstrook$$, $$natuurkunde-havo-2023-i-noodstopstrook-context8.png$$, 498, $$Door de kracht van de vrachtwagen op het net rollen de stalen banden af. Om zware vrachtwagens te stoppen, worden er meerdere vangnetten achter elkaar opgehangen. Ieder net hangt aan meerdere trommels. Iedere trommel is identiek. In figuur 7 zijn drie vangnetten in een klein deel van de noodstopstrook te zien.

figuur 7: foto van drie vangnetten, elk bevestigd aan meerdere trommels, in een met sneeuw bedekt deel van de noodstopstrook.$$, 'inline'),
  ('4706e281-f544-4f7d-9864-5b5c10e37048', '6f642084-5756-41f6-901f-42386e791087', $$vertraging mag nooit groter zijn dan 0,90·g, ongeacht formaat vrachtwagen; eerste net aan minder trommels dan overige netten$$, $$natuurkunde-havo-2023-i-noodstopstrook-context9.png$$, 498, $$De noodstopstrook moet zowel lichte als zware vrachtwagens veilig kunnen afremmen. Om veiligheidsredenen mag de vertraging nooit groter zijn dan 0,90∙g, ongeacht het formaat van de vrachtwagen.
Het eerste net is opgehangen aan minder trommels dan de overige netten.$$, 'inline'),
  ('e1629d80-ccf3-4357-87c6-b191a08df293', '6f642084-5756-41f6-901f-42386e791087', $$drie vangnetten aan 16 trommels; spankracht 2,0·10⁴ N per band; bandlengte 61 m; testvrachtwagen 60·10³ kg met snelheid 24 m s⁻¹$$, $$natuurkunde-havo-2023-i-noodstopstrook-context10.png$$, 498, $$De drie vangnetten in figuur 7 zijn bevestigd aan in totaal 16 trommels. De spankracht in iedere stalen band is constant 2,0·10⁴ N. De lengte van iedere band is 61 m.
Tijdens een test rijdt een vrachtwagen (m = 60·10³ kg) met een snelheid van 24 m s⁻¹ de noodstopstrook op.$$, 'inline'),
  ('3e76d62c-b662-4b22-a557-a525ca44caaa', '6f642084-5756-41f6-901f-42386e791087', $$uitwerkbijlage vraag 6 — (v,t)-diagram (figuur 2) met invulregels bij Bepaling:$$, $$natuurkunde-havo-2023-i-noodstopstrook-uitwerkbijlage-vraag6.png$$, 498, $$Uitwerkbijlage vraag 6: dezelfde (v,t)-grafiek als figuur 2 (v in m s⁻¹, 0 tot 30, tegen t in s, 0 tot 10), gevolgd door invulregels bij ''Bepaling:'' om de berekening toe te lichten.$$, 'uitwerkbijlage'),
  ('1a3ad4e6-f2b4-4820-baef-5214fae604f7', '6f642084-5756-41f6-901f-42386e791087', $$uitwerkbijlage vraag 7 — (v,t)-diagram (figuur 2) met invulregels bij Antwoord:$$, $$natuurkunde-havo-2023-i-noodstopstrook-uitwerkbijlage-vraag7.png$$, 498, $$Uitwerkbijlage vraag 7: dezelfde (v,t)-grafiek als figuur 2 (v in m s⁻¹, 0 tot 30, tegen t in s, 0 tot 10), gevolgd door invulregels bij ''Antwoord:'' om te laten zien hoe de maximale vertraging is bepaald.$$, 'uitwerkbijlage'),
  ('69f3a262-4c6f-44b2-b469-428bd9b76318', '6f642084-5756-41f6-901f-42386e791087', $$uitwerkbijlage vraag 8 — leeg (v,t)-assenstelsel om de grafiek voor de bevroren noodstopstrook in te schetsen$$, $$natuurkunde-havo-2023-i-noodstopstrook-uitwerkbijlage-vraag8.png$$, 498, $$Uitwerkbijlage vraag 8: dezelfde (v,t)-grafiek als figuur 2 (v in m s⁻¹, 0 tot 30, tegen t in s, 0 tot 10), waarin de leerling de grafiek voor het afremmen op een bevroren noodstopstrook moet schetsen.$$, 'uitwerkbijlage'),
  ('ffc9cc51-2691-4dee-b061-86697a8c6e50', '6f642084-5756-41f6-901f-42386e791087', $$uitwerkbijlage vraag 9 — situaties I (klein) en II (groot) met spankrachten van de stalen banden op het net$$, $$natuurkunde-havo-2023-i-noodstopstrook-uitwerkbijlage-vraag9.png$$, 498, $$Uitwerkbijlage vraag 9: twee situaties I en II, elk met een net (voorgesteld door twee bolletjes verbonden door lijnen) waarop twee stalen banden onder een hoek naar beneden aan het net trekken; in situatie II staan de bevestigingspunten van de banden verder uit elkaar dan in situatie I.$$, 'uitwerkbijlage'),
  ('b3d28982-80e7-4ede-8207-a2737bf1f7fb', '58545be6-d765-46bb-b69d-e146f058efeb', $$intro telescopen; figuur 1 — de Hubble-ruimtetelescoop$$, $$natuurkunde-havo-2023-i-kosmische-explosie-context1.png$$, 498, $$Sinds de uitvinding van de telescoop hebben sterrenkundigen steeds meer ontdekt over de sterrenhemel. Een bekende telescoop is de Hubble telescoop. Zie figuur 1.

figuur 1: foto van de Hubble-ruimtetelescoop in een baan om de aarde.

De Hubble is een ruimtetelescoop.$$, 'inline'),
  ('d8f37176-d936-4a2a-804d-ae89621d68df', '58545be6-d765-46bb-b69d-e146f058efeb', $$dubbelster KIC op 1,70·10¹⁹ m; figuur 2 — twee sterren om zwaartepunt Z; scheidingsformule (1); Hubble D=2,4 m, d=4,18·10⁹ m, fotonenergie 1,0 eV$$, $$natuurkunde-havo-2023-i-kosmische-explosie-context2.png$$, 498, $$Sommige sterren zitten in een dubbelster-systeem. Dit is een systeem van twee sterren die om een gemeenschappelijk zwaartepunt Z draaien. Zie schematisch in figuur 2.

figuur 2: schematische tekening van twee sterren (ster 1 en ster 2) die in een cirkelbaan om een gemeenschappelijk zwaartepunt Z draaien.

Een bepaalde dubbelster heeft de naam KIC9832227 (KIC) gekregen. Deze dubbelster staat op 1,70·10¹⁹ m afstand van de aarde.

Of twee sterren van een dubbelster met een telescoop als afzonderlijke lichtbronnen waar te nemen zijn, hangt af van een aantal variabelen. Twee sterren zijn nog net van elkaar te onderscheiden als geldt:

1,22·λ/D = d/ℓ (1)

Hierin is:
− λ de grootte van de golflengte van het licht dat van het object wordt waargenomen;
− D de diameter van de telescoop;
− d de afstand tussen de middelpunten van de sterren;
− ℓ de afstand van de aarde tot de dubbelster.

Hubble heeft een diameter van 2,4 m. Voor KIC geldt: d = 4,18·10⁹ m. Hubble neemt elektromagnetische straling waar met een fotonenergie van 1,0 eV.$$, 'inline'),
  ('5278a175-b08b-42ba-81b1-3cb3cd9239b1', '58545be6-d765-46bb-b69d-e146f058efeb', $$formule (2) d³/T² = k; frequentie verandert doordat sterren dichter naar elkaar toe bewegen$$, $$natuurkunde-havo-2023-i-kosmische-explosie-context3.png$$, 498, $$Voor het verband tussen de omlooptijd T van de twee sterren van KIC en de onderlinge afstand d geldt:

d³/T² = k (2)

Hierin is k een constante.

Enkele jaren geleden is bij dubbelster KIC geconstateerd dat de frequentie waarmee de twee sterren om het gemeenschappelijke zwaartepunt heen draaien verandert. Astronomen concludeerden uit deze verandering dat de sterren steeds dichter naar elkaar toe bewegen.$$, 'inline'),
  ('10808865-010f-4113-abbb-ae637f29a189', '58545be6-d765-46bb-b69d-e146f058efeb', $$samensmelting sterren = kosmische explosie; voorspelling 2017: explosie zichtbaar in 2023; afstand 1,70·10¹⁹ m; figuur 3 — tabel met vier historische periodes$$, $$natuurkunde-havo-2023-i-kosmische-explosie-context4.png$$, 498, $$Als sterren steeds dichter naar elkaar toe bewegen, kunnen ze uiteindelijk samensmelten in een kosmische explosie. Door de energie die bij zo'n samensmelting vrijkomt, wordt de helderheid van het zichtbare licht van de sterren tijdelijk veel groter.
In 2017 werd voorspeld dat in het jaar 2023 de kosmische explosie van dubbelster KIC op aarde te zien zou zijn.
Dubbelster KIC staat op 1,70·10¹⁹ m afstand van de aarde.
In figuur 3 staat een tabel met vier periodes.

figuur 3: tabel ''periode / kenmerkende gebeurtenis'' met de rijen 1: rond het jaar 0, begin Europese jaartelling; 2: rond het jaar 220, tijd van de Romeinen in Nederland; 3: rond het jaar 1800, ontstaan Koninkrijk der Nederlanden; 4: rond het jaar 2020, jouw middelbareschooltijd.$$, 'inline'),
  ('c2a0f4ef-e2c5-42f1-8420-7423611903ab', 'b6410ed6-5cc0-4063-969d-e655de52f156', $$intro tabaksplant; figuur 1 — tabaksoogst; vervalreeks Rn-222 via dochterkernen tot stabiel Pb-206$$, $$natuurkunde-havo-2023-i-radioactieve-rook-context1.png$$, 498, $$Tabak wordt gemaakt van de bladeren van de tabaksplant. Zie figuur 1.

figuur 1: foto van een landarbeider die tabaksbladeren oogst op een tabaksplantage.

Tabaksplanten halen water en (voedings)stoffen uit de bodem en de lucht. Hierin zitten ook radioactieve isotopen. Een van die isotopen is Rn-222, dat in een lange vervalreeks via diverse dochterkernen vervalt tot stabiel Pb-206:

²²²₈₆Rn →(α, 3,83 d) ²¹⁸₈₄Po →(α, 3,05 min) ²¹⁴₈₂Pb →(β, 26,8 min) ²¹⁴₈₃Bi →(β, 19,7 min) ²¹⁴₈₄Po →(α, 1,6·10⁻⁴ s) ²¹⁰₈₂Pb →(β, 22,6 j) ²¹⁰₈₃Bi →(β, 5,0 d) ²¹⁰₈₄Po →(α, 138 d) ²⁰⁶₈₂Pb

De dochterkernen uit deze vervalreeks komen in de bladeren van de tabaksplant terecht.
Van deze bladeren wordt tabak voor sigaretten gemaakt. De tijd tussen het oogsten van de plant en het roken van een sigaret van die plant is gemiddeld twee jaar.

Na twee jaar is vooral Pb-210 aanwezig in de tabak$$, 'inline'),
  ('5b5d933d-ddb6-4b66-9563-d0aac39113e7', 'b6410ed6-5cc0-4063-969d-e655de52f156', $$tabak bevat ook Po-210; sigaret 0,90 g tabak bevat 2·10⁵ atomen Po-210$$, $$natuurkunde-havo-2023-i-radioactieve-rook-context2.png$$, 498, $$Naast Pb-210 bevat tabak ook een klein aandeel van de zeer gevaarlijke radioactieve stof Po-210.
Een sigaret bevat 0,90 g tabak. Hierin zitten 2·10⁵ atomen Po-210.$$, 'inline'),
  ('d30ddf2f-17ad-4919-983c-79faa00c8d4e', 'b6410ed6-5cc0-4063-969d-e655de52f156', $$Po-210 concentreert zich op hotspots in de longen; formule (1) equivalente dosis H = wR·Agem·Δt·Ed/m$$, $$natuurkunde-havo-2023-i-radioactieve-rook-context3.png$$, 498, $$Van de totale massa van een sigaret komt een beperkt, maar wel zeer schadelijk deel via de rook in de kwetsbare longen terecht.
Het ingeademde Po-210 plakt door teer in de rook vast op kleine plekken in de longen, de zogenaamde hotspots.
De equivalente dosis H voor de longen als geheel, ten gevolge van het ingeademde polonium, kan berekend worden met de formule:

H = (wR · Agem · Δt · Ed) / m (1)

Hierin is:
− wR de weegfactor;
− Agem de gemiddelde activiteit;
− Δt de tijd dat het weefsel bestraald wordt;
− Ed de energie van het vrijgekomen α-deeltje;
− m de massa van het bestraalde weefsel.

Op de uitwerkbijlage staat een tabel met drie verschillende gegevens over Po-210 in de longen.$$, 'inline'),
  ('20e1b5f5-0987-499b-aa03-be1286b3fe6b', 'b6410ed6-5cc0-4063-969d-e655de52f156', $$uitwerkbijlage vraag 19 — tabel met drie gegevens over Po-210 in de longen en open ruimte voor de reden per gegeven$$, $$natuurkunde-havo-2023-i-radioactieve-rook-uitwerkbijlage-vraag19.png$$, 498, $$Uitwerkbijlage vraag 19: tabel met kolommen ''gegeven'' en ''Volgens formule (1) is Po-210 in de longen zo gevaarlijk omdat:''; rij 1: ''Po-210 is een α-straler.''; rij 2: ''Het door roken ingeademde Po-210 concentreert zich op hotspots in de longen.''; rij 3: ''Door het teer in de rook plakt Po-210 vast op plekken in de longen.''; met bij elke rij open (gestippelde) regels om de reden in te vullen.$$, 'uitwerkbijlage'),
  ('bd03a063-cbed-46cf-9c4a-60ce094dad72', 'b86a9736-8098-4714-8782-a706c4ba620d', $$intro zelfbouw zaklamp met leds (1,0·10² W bij 3,0 A) en 4 accus van 11,1 V$$, $$natuurkunde-havo-2023-i-zelfbouw-zaklamp-context1.png$$, 498, $$Een hobbyist maakt een zaklamp met een zeer grote lichtsterkte. Hij gebruikt voor de zaklamp meerdere leds. Iedere led heeft een vermogen van 1,0·10² W bij een stroomsterkte van 3,0 A. Voor de stroomvoorziening heeft hij de beschikking over 4 accu's die elk een spanning van 11,1 V leveren. Hij combineert een aantal van deze accu's tot een accupakket.$$, 'inline'),
  ('f2abd075-3fa2-4701-b38d-33d36fa13851', 'b86a9736-8098-4714-8782-a706c4ba620d', $$accupakket capaciteit 5,0 Ah; één led werkt op 3,0 A; 8 parallel geschakelde leds$$, $$natuurkunde-havo-2023-i-zelfbouw-zaklamp-context2.png$$, 498, $$Het gebruikte accupakket heeft een capaciteit van 5,0 Ah.
Eén led werkt op een stroomsterkte van 3,0 A. De zaklamp maakt gebruik van 8 parallel geschakelde leds.$$, 'inline'),
  ('c9e6cf76-7243-4cf5-8b11-eb813b26a9ff', 'b86a9736-8098-4714-8782-a706c4ba620d', $$led vermogen 1,0·10² W, rendement 35%; koelblok met 4 leds, 25 g water van 20 °C$$, $$natuurkunde-havo-2023-i-zelfbouw-zaklamp-context3.png$$, 498, $$Iedere led heeft een elektrisch vermogen van 1,0·10² W. De led levert licht en warmte. Het rendement van de leds is 35%. Om te voorkomen dat de leds te heet worden, zijn deze op koelblokken geplakt. Op één koelblok passen 4 leds. Het koelblok is gevuld met 25 gram water van 20 °C. Als de leds worden ingeschakeld, zal het water opwarmen.
Neem aan dat alle warmte die de leds produceren door het water wordt opgenomen.$$, 'inline'),
  ('35b4ee46-83fa-4f94-b281-23e5038615c6', 'b86a9736-8098-4714-8782-a706c4ba620d', $$koelsysteem met pomp, radiator en ventilator; figuur 1 — schema met warmtetransportplekken I, II en III$$, $$natuurkunde-havo-2023-i-zelfbouw-zaklamp-context4.png$$, 498, $$Om het water zelf te koelen, wordt het rondgepompt. Een pomp verplaatst het water van het koelblok naar een radiator die daardoor opwarmt. Een draaiende ventilator koelt de radiator door er lucht langs te blazen. Het afgekoelde water gaat weer terug naar het koelblok. Zie schematisch in figuur 1. Er zijn drie plekken (I, II en III) aangegeven waar warmte wordt getransporteerd.

figuur 1: schematische tekening van het koelcircuit met koelblok (met de leds erop, plek I), pomp, buizen naar de radiator (plek II) en een ventilator die lucht langs de radiator blaast (plek III), waarna het water terugstroomt naar het koelblok.

Op de uitwerkbijlage staat een tabel.$$, 'inline'),
  ('bc484ed0-967b-4fee-a2ba-e7feebc232e7', 'b86a9736-8098-4714-8782-a706c4ba620d', $$pomp en ventilator werken op dezelfde spanning als de leds, tegelijk ingeschakeld; figuur 2 — vier schakelschemas I t/m IV$$, $$natuurkunde-havo-2023-i-zelfbouw-zaklamp-context5.png$$, 498, $$Pomp p en ventilator f moeten tegelijk met de leds ingeschakeld worden en werken ieder op dezelfde spanning als de leds.
In figuur 2 staan vier schakelschema's.

figuur 2: vier schakelschema's (I, II, III en IV) met telkens een spanningsbron met schakelaar, de leds, en de pomp (p) en ventilator (f); in schema I en II staan p en f elk in een eigen parallelle tak met de schakelaar in serie met de leds-tak (in I na de aftakking, in II vóór de aftakking); in schema III zijn p en f in serie met elkaar in één parallelle tak met een eigen schakelaar; in schema IV staan p en f in serie met elkaar in dezelfde tak als de leds.$$, 'inline'),
  ('83e05e9c-fc08-4713-814f-38fd9c6a8e2e', 'b86a9736-8098-4714-8782-a706c4ba620d', $$vergelijking belichte oppervlaktes normale en zelfbouw zaklamp, gelijke intensiteit; figuur 3 (vierkant) en figuur 4 (cirkel, diameter = breedte gebouw)$$, $$natuurkunde-havo-2023-i-zelfbouw-zaklamp-context6.png$$, 498, $$De hobbyist wil tenslotte weten hoeveel licht zijn zelfbouw zaklamp geeft. Dit doet hij door de oppervlaktes te vergelijken die hij kan belichten met een zaklamp. Hij schijnt achtereenvolgens met een normale zaklamp en de zelfbouw zaklamp op de gevel van een gebouw. Zie figuren 3 en 4. De intensiteit (sterkte) van het licht op het gebouw is bij beide zaklampen gelijk. De normale zaklamp belicht een klein vierkant oppervlak. De zelfbouw zaklamp belicht een cirkelvormig oppervlak met dezelfde diameter als de breedte van het gebouw. In figuren 3 en 4 is dit gemarkeerd.

figuur 3: nachtfoto van een gebouw met een klein, vierkant verlicht vlak op de gevel (belicht door de normale zaklamp).
figuur 4: dezelfde nachtfoto van het gebouw, nu met een cirkel over de hele breedte van het gebouw getekend (het oppervlak dat door de zelfbouw zaklamp belicht wordt).$$, 'inline'),
  ('57e3f2ec-2f38-43c1-a56b-effd8426faee', 'b86a9736-8098-4714-8782-a706c4ba620d', $$uitwerkbijlage vraag 23 — tabel plek/situatie met stralling/stroming/geleiding om te omcirkelen$$, $$natuurkunde-havo-2023-i-zelfbouw-zaklamp-uitwerkbijlage-vraag23.png$$, 498, $$Uitwerkbijlage vraag 23: tabel met kolommen ''plek'', ''situatie'' en ''belangrijkste vorm van warmtetransport''; rij I: warmtetransport door de wand van het koelblok; rij II: warmtetransport van koelblok naar radiator; rij III: warmtetransport van de radiator naar de omgeving door het draaien van de ventilator; bij elke rij de opties ''straling'', ''stroming'' en ''geleiding'' om te omcirkelen.$$, 'uitwerkbijlage');

