  ('debb265b-4f56-45ac-ad4a-341b2020a6f1', '58545be6-d765-46bb-b69d-e146f058efeb', 13,
   $$[{"domain": "Aarde en heelal", "subdomain": "Zonnestelsel en heelal"}]$$::jsonb,
