   $$natuurkunde-havo-2023-i-kosmische-explosie-vraag15.png$$, 498, $$2p 15 Leg met behulp van formule (2) uit of de waargenomen frequentie toeneemt of afneemt.$$, array['5278a175-b08b-42ba-81b1-3cb3cd9239b1']::uuid[]),
  ('f48f10c5-027f-4de2-9edc-8cf2a9237881', '58545be6-d765-46bb-b69d-e146f058efeb', 16,
   $$[{"domain": "Aarde en heelal", "subdomain": "Zonnestelsel en heelal"}]$$::jsonb,
