   $$natuurkunde-havo-2023-i-kosmische-explosie-vraag16.png$$, 498, $$4p 16 Leg met behulp van een berekening uit in welke periode (1, 2, 3 of 4) de kosmische explosie volgens de voorspelling zou hebben plaatsgevonden.$$, array['10808865-010f-4113-abbb-ae637f29a189']::uuid[]),
  ('89abd51f-5809-42ef-badf-2731e750b331', 'b6410ed6-5cc0-4063-969d-e655de52f156', 17,
   $$[{"domain": "Beeld- en geluidstechniek", "subdomain": "Medische beeldvorming"}]$$::jsonb,
